package com.thang.nihongo_user.service;
import com.thang.nihongo_user.model.*;import com.thang.nihongo_user.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.time.*;import java.math.BigDecimal;
@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class CourseRefundService {
 private final CoursePurchaseRepository purchases;private final CourseRefundRepository refunds;private final IUserWalletRepository wallets;private final IWalletTransactionRepository ledger;private final AdminCommerceAuditRepository audit;private final EntityManager em;
 public record Request(@NotNull @Positive Long purchaseId,@NotBlank @Size(min=10,max=500) String reason,boolean revokeAccess){}
 public record Review(boolean approve,@NotBlank @Size(min=10,max=500) String note,long version){}
 public Page<CoursePurchase> purchases(String userId,int page){return userId==null||userId.isBlank()?purchases.findAllByOrderByCreatedAtDescIdDesc(page(page)):purchases.findByUserIdOrderByCreatedAtDescIdDesc(userId,page(page));}
 public Page<CourseRefund> list(String status,int page){if(status!=null&&!java.util.List.of("PENDING","APPROVED","REJECTED").contains(status))throw bad("Trạng thái không hợp lệ");return status==null?refunds.findAllByOrderByCreatedAtDescIdDesc(page(page)):refunds.findByStatusOrderByCreatedAtDescIdDesc(status,page(page));}
 public Page<CourseRefund> mine(String userId,int page){return refunds.findByUserIdOrderByCreatedAtDescIdDesc(userId,page(page));}
 @Transactional public CourseRefund request(String actor,Request input){var purchase=em.find(CoursePurchase.class,input.purchaseId(),LockModeType.PESSIMISTIC_WRITE);if(purchase==null)throw missing();if(purchase.getAmount().signum()<=0)throw bad("Giao dịch không có khoản tiền để hoàn");var existing=refunds.findByPurchaseId(purchase.getId()).orElse(null);if(existing!=null){if(existing.getReason().equals(input.reason().trim())&&existing.isRevokeAccess()==input.revokeAccess())return existing;throw conflict("Giao dịch đã có yêu cầu hoàn tiền");}var row=new CourseRefund();row.setPurchaseId(purchase.getId());row.setUserId(purchase.getUserId());row.setRequestedBy(actor);row.setReason(input.reason().trim());row.setAmount(purchase.getAmount());row.setRevokeAccess(input.revokeAccess());row.setCreatedAt(LocalDateTime.now());row=refunds.saveAndFlush(row);audit(actor,"REFUND_REQUEST",row,"Yêu cầu hoàn "+row.getAmount()+" / "+row.getReason());return row;}
 @Transactional public CourseRefund review(String actor,Long id,Review input){var reference=refunds.findById(id).orElseThrow(CourseRefundService::missing);wallets.ensureWallet(reference.getUserId());var wallet=wallets.findByUserIdForUpdate(reference.getUserId()).orElseThrow();var row=refunds.lock(id).orElseThrow(CourseRefundService::missing);if(!row.getStatus().equals("PENDING")){if(input.approve()&&row.getStatus().equals("APPROVED")||!input.approve()&&row.getStatus().equals("REJECTED"))return row;throw conflict("Yêu cầu đã được xử lý");}if(input.version()!=row.getVersion())throw conflict("Yêu cầu đã được cập nhật");var purchase=em.find(CoursePurchase.class,row.getPurchaseId(),LockModeType.PESSIMISTIC_WRITE);if(purchase==null||!purchase.getUserId().equals(row.getUserId())||purchase.getAmount().compareTo(row.getAmount())!=0)throw conflict("Giao dịch gốc không còn phù hợp");if(input.approve()){var before=wallet.getBalance();var after=before.add(row.getAmount());if(after.compareTo(new BigDecimal("9999999999999.99"))>0)throw conflict("Số dư vượt giới hạn");wallet.setBalance(after);ledger.save(WalletTransaction.builder().walletId(wallet.getWalletId()).transactionType(WalletTransactionType.REFUND).amount(row.getAmount()).balanceBefore(before).balanceAfter(after).referenceType("COURSE_REFUND").referenceId(row.getId()).description("Hoàn giao dịch "+purchase.getId()).status(WalletTransactionStatus.SUCCESS).build());if(row.isRevokeAccess()){var subscription=em.find(UserSubscription.class,purchase.getSubscriptionId(),LockModeType.PESSIMISTIC_WRITE);if(subscription==null||!row.getUserId().equals(subscription.getUserId())||!purchase.getCourseId().equals(subscription.getCourseId()))throw conflict("Đăng ký không thuộc giao dịch");subscription.setStatus(SubscriptionStatus.EXPIRED);subscription.setExpiredAt(LocalDateTime.now());}}row.setStatus(input.approve()?"APPROVED":"REJECTED");row.setReviewedBy(actor);row.setReviewNote(input.note().trim());row.setReviewedAt(LocalDateTime.now());audit(actor,input.approve()?"REFUND_APPROVE":"REFUND_REJECT",row,row.getAmount()+" / "+row.getReviewNote()+" / revokeAccess="+row.isRevokeAccess());return row;}
 private void audit(String actor,String action,CourseRefund row,String detail){var a=new AdminCommerceAudit();a.setActor(actor);a.setAction(action);a.setTarget("refund:"+row.getId());a.setDetail(detail);a.setCreatedAt(LocalDateTime.now());audit.save(a);}
 private Pageable page(int page){if(page<0)throw bad("Trang không hợp lệ");return PageRequest.of(page,20);}private static ResponseStatusException bad(String text){return new ResponseStatusException(HttpStatus.BAD_REQUEST,text);}private static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy giao dịch");}private static ResponseStatusException conflict(String text){return new ResponseStatusException(HttpStatus.CONFLICT,text);}
}
